<?php require_once __DIR__ . '/_common.php';
$total = $conn->query("SELECT COUNT(*) c FROM products WHERE vendor_id=$vendor_id")->fetch_assoc()['c'];
$stock = $conn->query("SELECT COALESCE(SUM(stock),0) c FROM products WHERE vendor_id=$vendor_id")->fetch_assoc()['c'];
$low = $conn->query("SELECT COUNT(*) c FROM products WHERE vendor_id=$vendor_id AND stock BETWEEN 1 AND 5")->fetch_assoc()['c'];
$sales = $conn->query("SELECT COALESCE(SUM(oi.quantity*oi.price),0) total FROM order_items oi JOIN orders o ON oi.order_id=o.id WHERE oi.vendor_id=$vendor_id AND o.status <> 'cancelled'")->fetch_assoc()['total'];
$recent = $conn->query("SELECT p.*, COUNT(oi.id) order_lines FROM products p LEFT JOIN order_items oi ON p.id=oi.product_id WHERE p.vendor_id=$vendor_id GROUP BY p.id ORDER BY p.created_at DESC LIMIT 6");
?>
