e-50">Units in stock</div><h2><?= (int)$stock ?></h2></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="text-white-50">Low stock</div><h2><?= (int)$low ?></h2></div></div><div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="text-white-50">Sales value</div><h2>₹<?=number_format((float)$sales,2)?></h2></div></div></div><div class="glass-card p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h4 class="text-white mb-0">Recent Products</h4><a href="products.php" class="btn btn-light-soft btn-sm">View all</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><?php while($p=$recent->fetch_assoc()): ?><tr><td><?=htmlspecialchars($p['name'])?></td><td>₹<?=number_format($p['price'],2)?></td><td><?=$p['stock']?></td><td><?=htmlspecialchars($p['status'])?></td><td><a class="btn btn-light-soft btn-sm" href="edit_product.php?id=<?=$p['id']?>">Edit</a></td></tr><?php endwhile; ?></tbody></table></div></div></div></main></div></div></body></html>
